PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE reports (
  id TEXT PRIMARY KEY NOT NULL,                      -- uuid v4
  harness_id TEXT NOT NULL REFERENCES harnesses(id),
  reporter_github_user_id INTEGER NOT NULL,
  reporter_github_login TEXT NOT NULL,
  reason TEXT NOT NULL,                              -- short prose, ≤ 1000 chars
  ip_hash TEXT,                                      -- hashed reporter IP (per-report; dedupe)
  status TEXT NOT NULL DEFAULT 'pending',            -- pending | resolved_unlist | resolved_dismiss
  resolved_at INTEGER,
  resolved_by_operator_note TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE publish_rate_limit (
  github_user_id INTEGER NOT NULL,
  window_start INTEGER NOT NULL,                     -- unix ms, floor(now/3600000)*3600000
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (github_user_id, window_start)
);
CREATE TABLE indexer_runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  started_at INTEGER NOT NULL,
  finished_at INTEGER,
  harnesses_examined INTEGER NOT NULL DEFAULT 0,
  harnesses_updated INTEGER NOT NULL DEFAULT 0,
  errors_count INTEGER NOT NULL DEFAULT 0,
  error_summary TEXT                                 -- last-error sample, not exhaustive
);
CREATE TABLE audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts INTEGER NOT NULL,
  kind TEXT NOT NULL,
  detail TEXT
);
CREATE TABLE banned_publisher_pubkeys (
  pubkey TEXT PRIMARY KEY NOT NULL,            -- base64 Ed25519 device pubkey
  reason TEXT NOT NULL,                         -- 'abuse' | 'spam' | 'impersonation' | ...
  added_at INTEGER NOT NULL,                    -- unix ms
  added_by_operator_user_id INTEGER,            -- nullable: imported / system ban
  updated_at INTEGER NOT NULL                   -- unix ms
);
CREATE TABLE IF NOT EXISTS "harnesses" (
  id TEXT PRIMARY KEY NOT NULL,                      -- uuid v4 (unchanged)

  listing_kind TEXT NOT NULL DEFAULT 'harness'
    CHECK (listing_kind IN ('harness', 'blueprint', 'plugin', 'tool-pack', 'learning-pack', 'template')),
  project_ref TEXT,
  listing_ref TEXT,

  github_repository_id INTEGER NOT NULL,
  github_owner TEXT NOT NULL,
  github_name TEXT NOT NULL,
  github_url TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  topic_hex TEXT,
  publisher_github_user_id INTEGER NOT NULL,
  publisher_github_login TEXT NOT NULL,
  publisher_permission TEXT,                          -- migration 002
  publisher_device_pubkey TEXT,                       -- migration 003
  publisher_attestation_gist_id TEXT,                 -- migration 003
  claim_status TEXT NOT NULL DEFAULT 'unclaimed',
  claimant_github_user_id INTEGER,
  claimant_github_login TEXT,
  superseded_by TEXT,
  stars INTEGER NOT NULL DEFAULT 0,
  contributor_count INTEGER NOT NULL DEFAULT 0,
  last_activity_at INTEGER,
  languages TEXT,
  stats_refreshed_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  unlisted_at INTEGER,
  unlisted_reason TEXT,

  -- migration 005 (vestigial tarball pointers; snapshot kind retired)
  tarball_r2_key TEXT,
  tarball_content_hash TEXT,
  tarball_bytes INTEGER,

  -- migration 006
  provides_tools TEXT,

  -- migration 007
  hive_pubkey TEXT,
  hive_title TEXT,

  -- migration 008: pre-publication review (D-007)
  review_status TEXT NOT NULL DEFAULT 'approved'
    CHECK (review_status IN ('pending', 'approved', 'rejected')),
  reviewed_at INTEGER,
  review_reason TEXT,

  -- migration 009: blueprint.yaml kind discriminator (ADDITIVE column —
  -- carried forward here; dropping it from a rebuild loses data silently)
  blueprint_kind TEXT
, template_category TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX reports_pending_idx
  ON reports (status, created_at)
  WHERE status = 'pending';
CREATE INDEX reports_harness_idx
  ON reports (harness_id);
CREATE INDEX audit_kind_idx ON audit (kind, ts DESC);
CREATE INDEX banned_pubkeys_added_at_idx
  ON banned_publisher_pubkeys (added_at DESC);
CREATE INDEX harnesses_listed_idx
  ON harnesses (unlisted_at, last_activity_at DESC);
CREATE INDEX harnesses_publisher_idx
  ON harnesses (publisher_github_user_id);
CREATE INDEX harnesses_kind_idx
  ON harnesses (listing_kind, unlisted_at, last_activity_at DESC);
CREATE INDEX harnesses_project_idx
  ON harnesses (project_ref) WHERE project_ref IS NOT NULL;
CREATE UNIQUE INDEX harnesses_active_harness_repo_unique
  ON harnesses (github_repository_id)
  WHERE listing_kind = 'harness' AND unlisted_at IS NULL;
CREATE UNIQUE INDEX harnesses_active_listing_unique
  ON harnesses (github_repository_id, listing_kind, listing_ref)
  WHERE listing_kind != 'harness' AND unlisted_at IS NULL;
CREATE INDEX harnesses_tarball_key_idx
  ON harnesses (tarball_r2_key) WHERE tarball_r2_key IS NOT NULL;
CREATE INDEX harnesses_hive_pubkey_idx
  ON harnesses (hive_pubkey) WHERE hive_pubkey IS NOT NULL;
CREATE INDEX harnesses_review_pending_idx
  ON harnesses (created_at DESC) WHERE review_status = 'pending';
